starter:
def classify_status(status_code):
    # верни одну из строк: "2xx success", "3xx redirect", "4xx client error", "5xx server error", "unknown"
    pass


def is_success_ternary(status_code):
    # используя тернарный оператор, верни True, если status_code в диапазоне [200; 299], иначе False
    pass

tests:
def test_classify_2xx():
    assert classify_status(204) == "2xx success", "204 должен классифицироваться как 2xx success"


def test_classify_3xx():
    assert classify_status(301) == "3xx redirect", "301 должен классифицироваться как 3xx redirect"


def test_classify_4xx():
    assert classify_status(404) == "4xx client error", "404 должен классифицироваться как 4xx client error"


def test_classify_5xx():
    assert classify_status(500) == "5xx server error", "500 должен классифицироваться как 5xx server error"


def test_classify_unknown():
    assert classify_status(100) == "unknown", "100 не попадает ни в один из диапазонов 2xx-5xx"


def test_is_success_ternary():
    assert is_success_ternary(204) is True, "204 входит в диапазон [200; 299] - успешный"
    assert is_success_ternary(404) is False, "404 не входит в диапазон [200; 299] - не успешный"
